<?php require_once dirname(__DIR__,2).'/bootstrap.php';require_post();$me=require_auth();$d=request_json();$uid=(int)$me['id'];$target=(int)($d['userId']??0);if($target<1||$target===$uid)json_response(['message'=>'Bu kullanıcı takip edilemez.'],400);$p=db();try{$p->beginTransaction();$owner=v17_query('SELECT * FROM users WHERE id=? FOR UPDATE',[$target])->fetch();if(!$owner)json_response(['message'=>'Kullanıcı bulunamadı.'],404);$following=(bool)v17_query('SELECT 1 FROM follows WHERE follower_user_id=? AND followed_user_id=?',[$uid,$target])->fetchColumn();$pending=(bool)v17_query('SELECT 1 FROM follow_requests WHERE requester_user_id=? AND target_user_id=?',[$uid,$target])->fetchColumn();if($following){v17_query('DELETE FROM follows WHERE follower_user_id=? AND followed_user_id=?',[$uid,$target]);$following=false;$message='Takipten çıkarıldı.';}elseif($pending){v17_query('DELETE FROM follow_requests WHERE requester_user_id=? AND target_user_id=?',[$uid,$target]);$pending=false;$message='İstek geri alındı.';}elseif($owner['is_private']){v17_query('INSERT IGNORE INTO follow_requests(requester_user_id,target_user_id) VALUES (?,?)',[$uid,$target]);$pending=true;$message='Takip isteği gönderildi.';create_notification($target,$uid,'follow_request','Takip isteği',$me['display_name'].' seni takip etmek istiyor.','./profile.php#follow-requests');}else{v17_query('INSERT IGNORE INTO follows(follower_user_id,followed_user_id) VALUES (?,?)',[$uid,$target]);$following=true;$message='Takip edildi.';create_notification($target,$uid,'follow','Yeni takipçi',$me['display_name'].' seni takip ediyor.','./channel.php?id='.$uid);}$count=(int)v17_query('SELECT COUNT(*) FROM follows WHERE followed_user_id=?',[$target])->fetchColumn();$p->commit();json_response(['following'=>$following,'pending'=>$pending,'followerCount'=>$count,'message'=>$message]);}catch(Throwable $e){if($p->inTransaction())$p->rollBack();json_response(['message'=>'Takip işlemi tamamlanamadı.'],500);}